package org.sleepwell.app;

import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class AlarmPlaybackTest {
    static class Fake implements AlarmPlayback.Sink {
        long now;int stops,errors;boolean throwClose,async;List<String> events=new ArrayList<>();List<Layer> layers=new ArrayList<>();
        class Layer implements AlarmPlayback.Layer {String tone;AlarmPlayback.Ready callback,activated;float gain=-1;int starts;boolean closed;Layer(String tone){this.tone=tone;}public void prepare(AlarmPlayback.Ready callback){this.callback=callback;}public void gain(float value){assertFalse(closed);gain=value;events.add("gain:"+value);}public void start(AlarmPlayback.Ready activated){assertFalse(closed);assertTrue(gain>=0);this.activated=activated;events.add("start");starts++;if(!async)activated.ready();}public void close(){closed=true;if(throwClose)throw new IllegalStateException();}}
        public AlarmPlayback.Layer create(String tone){Layer layer=new Layer(tone);layers.add(layer);return layer;}
        public void volume(AlarmPlayback.Layer layer,AlarmWakePolicy policy,boolean backup){events.add("stream:"+policy.streamLevel(15,backup));}
        public void stopped(){stops++;}public void failed(){errors++;}
    }
    private AlarmPlayback engine(Alarm a,Fake f){return new AlarmPlayback(a,f,()->f.now,()->f.now);}
    @Test public void gainAndStreamPrecedeStartAndRampUsesRealElapsedClock(){Fake f=new Fake();Alarm a=new Alarm(1);a.volume=80;a.rampSeconds=120;AlarmPlayback e=engine(a,f);e.start();f.layers.get(0).callback.ready();assertEquals(List.of("gain:0.0","stream:12","start"),f.events);f.now=60000;e.tick();assertEquals(.25,f.layers.get(0).gain,0);f.now=120000;e.tick();assertEquals(1,f.layers.get(0).gain,0);assertEquals(1,f.layers.get(0).starts);}
    @Test public void delayDoesNotStartSilentLoopAndStopCancelsReady(){Fake f=new Fake();Alarm a=new Alarm(1);a.soundDelaySeconds=60;AlarmPlayback e=engine(a,f);e.start();f.layers.get(0).callback.ready();assertEquals(0,f.layers.get(0).starts);f.now=59999;e.tick();assertEquals(0,f.layers.get(0).starts);e.stop();f.now=60000;e.tick();f.layers.get(0).callback.ready();assertEquals(0,f.layers.get(0).starts);assertEquals(1,f.stops);}
    @Test public void lateReadyContinuesOccurrenceEnvelopeInsteadOfRestarting(){Fake f=new Fake();Alarm a=new Alarm(1);a.rampSeconds=120;AlarmPlayback e=engine(a,f);e.start();f.now=60000;f.layers.get(0).callback.ready();assertEquals(.25,f.layers.get(0).gain,0);}
    @Test public void duplicateStartsWhileLoadingDoNotAllocateOrRestart(){Fake f=new Fake();AlarmPlayback e=engine(new Alarm(1),f);e.start();e.start();assertEquals(1,f.layers.size());f.layers.get(0).callback.ready();e.start();assertEquals(1,f.layers.get(0).starts);}
    @Test public void timeoutFallsBackOnceAndStaleReadyCannotStart(){Fake f=new Fake();Alarm a=new Alarm(1);a.tone="content://removed";AlarmPlayback e=engine(a,f);e.start();Fake.Layer old=f.layers.get(0);f.now=4000;e.tick();assertTrue(old.closed);assertEquals("daybreak",f.layers.get(1).tone);old.callback.ready();old.callback.failed();assertEquals(0,old.starts);f.layers.get(1).callback.ready();assertEquals(1,f.layers.get(1).starts);}
    @Test public void bothFailuresRemainBoundedUntilExplicitNewOccurrence(){Fake f=new Fake();AlarmPlayback e=engine(new Alarm(1),f);e.start();f.layers.get(0).callback.failed();f.layers.get(1).callback.failed();f.now=99999;e.tick();e.start();assertEquals(2,f.layers.size());assertEquals(1,f.errors);}
    @Test public void failedBackupKeepsWorkingPrimaryAndRaisesItsTarget(){Fake f=new Fake();AlarmPlayback e=engine(new Alarm(1),f);e.start();Fake.Layer primary=f.layers.get(0);primary.callback.ready();e.backup();assertFalse(primary.closed);f.layers.get(1).callback.failed();assertFalse(primary.closed);assertEquals(1,primary.starts);assertEquals(1,primary.gain,0);assertEquals("stream:15",f.events.get(f.events.size()-2));}
    @Test public void successfulBackupClosesPrimaryOnlyAfterReplacementStarts(){Fake f=new Fake();AlarmPlayback e=engine(new Alarm(1),f);e.start();f.layers.get(0).callback.ready();e.backup();assertFalse(f.layers.get(0).closed);f.layers.get(1).callback.ready();assertTrue(f.layers.get(0).closed);assertEquals("pulse",f.layers.get(1).tone);assertEquals(1,f.layers.get(1).gain,0);}
    @Test public void quietBackupRequestNeverAllocatesOrIncreasesVolume(){Fake f=new Fake();Alarm a=new Alarm(-1);a.extraLoud=true;a.volume=100;AlarmPlayback e=engine(a,f);e.start();f.layers.get(0).callback.ready();e.backup();assertEquals(1,f.layers.size());assertEquals(List.of("gain:1.0","stream:3","start"),f.events);}
    @Test public void cleanupContinuesWhenLayerCloseThrowsAndLateCallbacksCannotStart(){Fake f=new Fake();AlarmPlayback e=engine(new Alarm(1),f);e.start();f.layers.get(0).callback.failed();f.throwClose=true;e.stop();e.stop();for(Fake.Layer layer:f.layers){assertTrue(layer.closed);layer.callback.ready();assertEquals(0,layer.starts);}assertEquals(1,f.stops);}
    @Test public void staleBackupCannotEscalateDifferentOrQuietOccurrence(){assertTrue(AlarmReceiver.backupMatches(true,1,1,"a","a"));assertFalse(AlarmReceiver.backupMatches(true,1,2,"a","a"));assertFalse(AlarmReceiver.backupMatches(true,-1,-1,"a","a"));assertFalse(AlarmReceiver.backupMatches(true,1,1,"a","old"));assertFalse(AlarmReceiver.backupMatches(false,1,1,"a","a"));assertFalse(AlarmReceiver.backupMatches(true,1,1,"",null));}
    @Test public void asynchronousBackupFailureDoesNotClosePrimary(){Fake f=new Fake();AlarmPlayback e=engine(new Alarm(1),f);e.start();f.layers.get(0).callback.ready();f.async=true;e.backup();f.layers.get(1).callback.ready();assertFalse(f.layers.get(0).closed);f.layers.get(1).activated.failed();assertFalse(f.layers.get(0).closed);assertTrue(f.layers.get(1).closed);}
    @Test public void asynchronousBackupSuccessCommitsOnlyAfterAcknowledgement(){Fake f=new Fake();AlarmPlayback e=engine(new Alarm(1),f);e.start();f.layers.get(0).callback.ready();f.async=true;e.backup();f.layers.get(1).callback.ready();assertFalse(f.layers.get(0).closed);e.tick();assertEquals(1,f.layers.get(1).starts);f.layers.get(1).activated.ready();assertTrue(f.layers.get(0).closed);}
    @Test public void retainedPrimaryErrorAfterBackupFailureStillFallsBack(){Fake f=new Fake();AlarmPlayback e=engine(new Alarm(1),f);e.start();f.layers.get(0).callback.ready();e.backup();f.layers.get(1).callback.failed();f.layers.get(0).callback.failed();assertTrue(f.layers.get(0).closed);assertEquals(3,f.layers.size());assertEquals("daybreak",f.layers.get(2).tone);f.layers.get(2).callback.ready();assertEquals(1,f.layers.get(2).starts);}
    @Test public void backupIdentitiesSeparateRepeatedOccurrencesOfTheSameAlarm(){assertNotEquals(Scheduler.backupIdentity(1,"old"),Scheduler.backupIdentity(1,"new"));assertNotEquals(Scheduler.backupIdentity(1,"run"),Scheduler.backupIdentity(2,"run"));}
}
